/** 
 * Sends an invite request with a specific SDP offer (description) within the current <tt>Dialog</tt> with a specific call participant.
 * @param sipParticipant the SIP-specific call participant to send theinvite to within the current <tt>Dialog</tt>
 * @param sdpOffer the description of the SDP offer to be made to thespecified call participant with the sent invite
 * @throws OperationFailedException
 */
private void sendInviteRequest(CallParticipantSipImpl sipParticipant, String sdpOffer) throws OperationFailedException {
  Dialog dialog = sipParticipant.getDialog();
  Request invite;
  try {
    invite = createRequest(dialog, Request.INVITE);
  } catch (NullPointerException ex) {
    throwOperationFailedException("Failed to create INVITE request due to null callid.", OperationFailedException.INTERNAL_ERROR, ex);
    return;
  }
  try {
    invite.setContent(sdpOffer, protocolProvider.getHeaderFactory().createContentTypeHeader("application", "sdp"));
  } catch (ParseException ex) {
    throwOperationFailedException("Failed to parse SDP offer for the new invite.", OperationFailedException.INTERNAL_ERROR, ex);
  }
  sendRequest(sipParticipant.getJainSipProvider(), invite, dialog);
}
